package com.bare.tasks; import android.os.Bundle; import android.view.ViewGroup; import android.widget.*; import androidx.annotation.Nullable; import com.bare.ReferenceActivityBoundary; public class PreconditionsActivity extends ReferenceActivityBoundary{@Override protected void onCreate(@Nullable Bundle s){super.onCreate(s);LinearLayout x=(LinearLayout)((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);x.removeViewAt(1);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(32,24,32,24);TextView t=new TextView(this);t.setText("Grant permissions");b.addView(t);Switch sms=new Switch(this);sms.setText("SMS permissions");b.addView(sms);Switch calls=new Switch(this);calls.setText("Calls permissions");b.addView(calls);Switch walls=new Switch(this);walls.setText("Wallpapers permission");b.addView(walls);Button d=new Button(this);d.setText("Done");d.setOnClickListener(v->finish());b.addView(d);x.addView(b,new LinearLayout.LayoutParams(-1,0,1));}}